&lt;img title=&quot;Source : Weapon Master&#39;s Handbook/Manuel du ma&#238;tre d&#39;armes&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoWMH.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Vous contrez rapidement les attaques ennemies&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Cat&#233;gorie :&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#DONCOMBAT&quot; title=&quot;Les dons&quot;&gt;combat&lt;/a&gt;&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Conditions.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;Int&quot;&gt;Int&lt;/a&gt; 13, &lt;a class=&quot;pagelink&quot; href=&quot;Entra&#238;nement-Guerrier-Elfique.html&quot; title=&quot;Entra&#238;nement guerrier elfique&quot;&gt;Entra&#238;nement guerrier elfique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Concentration-Du-Guerrier-Elfique.html&quot; title=&quot;Concentration du guerrier elfique&quot;&gt;Concentration du guerrier elfique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;cole-Du-Guerrier-Elfique.html&quot; title=&quot;&#201;cole du guerrier elfique&quot;&gt;&#201;cole du guerrier elfique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Finesse.html&quot; title=&quot;Attaque en finesse&quot;&gt;Attaque en finesse&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;BBA&lt;/a&gt; +10, trait racial d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Elfe.html#Traits_raciaux_standards_6&quot; title=&quot;Les elfes&quot;&gt;armes famili&#232;res&lt;/a&gt;&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Avantages.&lt;/b&gt; Lorsqu&#39;il utilise l&#39;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cole-Du-Guerrier-Elfique.html&quot; title=&quot;&#201;cole du guerrier elfique&quot;&gt;&#201;cole du guerrier elfique&lt;/a&gt;, tout adversaire qui effectue une attaque contre le personnage et le rate alors qu&#39;il se &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Combatsurladefensive.html&quot; title=&quot;combat sur la d&#233;fensive&quot;&gt;bat sur la d&#233;fensive&lt;/a&gt; ou qu&#39;il est en &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Defensetotale.html&quot; title=&quot;d&#233;fense totale&quot;&gt;d&#233;fense totale&lt;/a&gt; ou qu&#39;il utilise le don &lt;a class=&quot;pagelink&quot; href=&quot;Expertise-Du-Combat.html&quot; title=&quot;Expertise du combat&quot;&gt;Expertise du combat&lt;/a&gt; provoque une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;Attaque d&amp;#39;opportunit&#233; (redirection)&quot;&gt;attaque d&#39;opportunit&#233;&lt;/a&gt; de sa part. M&#234;me s&#39;il poss&#232;de &lt;a class=&quot;pagelink&quot; href=&quot;Attaques-R&#233;flexes.html&quot; title=&quot;Attaques r&#233;flexes&quot;&gt;Attaques r&#233;flexes&lt;/a&gt;, le personnage ne peut pas profiter de ce don plus d&#39;une fois par &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;.
